    "settings.diagnostics.providerRequestTrace.description": "有効にすると、1 つの論理 Provider リクエストについて、最終的な送信リクエストと各物理リトライが 1 つのグループにまとめて記録されます。内容はレスポンスメタデータ、パーサー前の生レスポンスバイト、チャンクまたは WebSocket フレームの境界、失敗時の結果です。所属セッションの temp/provider-api-trace ディレクトリは 4 つの論理リクエストスロットをローテーションし、各試行では失敗や手動キャンセル前に受信したバイトを含め最大 64 MiB の生レスポンスを保持します。VCE の埋め込みバッチタスクも、正確なリクエストファイルと Provider の完全な output/error ファイルを、アプリケーションデータディレクトリの temp/vce 配下にプロジェクトとタスクごとに分けて保持し、自動ローテーションは行いません。ファイルにはプロンプト、ソースコード、ツール引数、ツール結果、Provider の出力が含まれる可能性があります。問題の診断中のみ有効にしてください。",
